exercises.solution:
function amicablePairs(limit) {
  function sumDivisors(n) {
    let sum = 1;
    for (let i = 2; i * i <= n; i++) {
      if (n % i === 0) {
        sum += i;
        if (i !== n / i) sum += n / i;
      }
    }
    return sum;
  }
  const pairs = [];
  for (let a = 2; a < limit; a++) {
    const b = sumDivisors(a);
    if (b > a && b < limit && sumDivisors(b) === a) {
      pairs.push([a, b]);
    }
  }
  return pairs;
}

