exercises.solution:
function modInverse(a, mod) {
  function extGcd(a, b) {
    if (b === 0) return { gcd: a, x: 1, y: 0 };
    const { gcd, x, y } = extGcd(b, a % b);
    return { gcd, x: y, y: x - Math.floor(a / b) * y };
  }
  const { gcd, x } = extGcd(a, mod);
  if (gcd !== 1) return -1;
  return ((x % mod) + mod) % mod;
}

