exercises.solution:
function numberTheory(n) {
  // Prime check
  function checkPrime(num) {
    if (num < 2) return false;
    for (let i = 2; i * i <= num; i++) if (num % i === 0) return false;
    return true;
  }
  // Prime factors
  function getFactors(num) {
    const f = [];
    let temp = num;
    for (let d = 2; d * d <= temp; d++) {
      while (temp % d === 0) { f.push(d); temp /= d; }
    }
    if (temp > 1) f.push(temp);
    return f;
  }
  // Divisors
  function getDivisors(num) {
    const divs = [];
    for (let i = 1; i * i <= num; i++) {
      if (num % i === 0) { divs.push(i); if (i !== num / i) divs.push(num / i); }
    }
    return divs;
  }
  // Totient
  function phi(num) {
    let result = num, temp = num;
    for (let p = 2; p * p <= temp; p++) {
      if (temp % p === 0) { while (temp % p === 0) temp /= p; result -= result / p; }
    }
    if (temp > 1) result -= result / temp;
    return result;
  }
  // Digital root
  function digRoot(num) {
    while (num >= 10) {
      let s = 0, t = num;
      while (t > 0) { s += t % 10; t = Math.floor(t / 10); }
      num = s;
    }
    return num;
  }
  const divs = getDivisors(n);
  const divisorSum = divs.reduce((a, b) => a + b, 0);
  return {
    isPrime: checkPrime(n),
    factors: getFactors(n),
    divisorCount: divs.length,
    divisorSum,
    totient: phi(n),
    isPerfect: divisorSum - n === n,
    digitalRoot: digRoot(n)
  };
}

