exercises.solution:
function regularPolygon(n, s) {
  const intAngle = (n - 2) * 180 / n;
  const extAngle = 360 / n;
  const perimeter = n * s;
  const apothem = s / (2 * Math.tan(Math.PI / n));
  const area = (perimeter * apothem) / 2;
  const circumradius = s / (2 * Math.sin(Math.PI / n));
  return {
    interiorAngle: Math.round(intAngle * 100) / 100,
    exteriorAngle: Math.round(extAngle * 100) / 100,
    perimeter,
    apothem: Math.round(apothem * 10000) / 10000,
    area: Math.round(area * 100) / 100,
    circumradius: Math.round(circumradius * 10000) / 10000
  };
}

