function mode(nums) {
  const freq = {};
  for (const n of nums) {
    freq[n] = (freq[n] || 0) + 1;
  }
  const maxFreq = Math.max(...Object.values(freq));
  return Object.keys(freq)
    .filter(k => freq[k] === maxFreq)
    .map(Number)
    .sort((a, b) => a - b);
}

