function movingAverage(data, k) {
  const result = [];
  for (let i = k - 1; i < data.length; i++) {
    let sum = 0;
    for (let j = i - k + 1; j <= i; j++) {
      sum += data[j];
    }
    result.push(Math.round((sum / k) * 100) / 100);
  }
  return result;
}

