exercises.solution:
function detectOutliers(data) {
  const sorted = [...data].sort((a, b) => a - b);
  function pctile(arr, k) {
    const idx = (k / 100) * (arr.length - 1);
    const lo = Math.floor(idx);
    const hi = Math.ceil(idx);
    if (lo === hi) return arr[lo];
    const frac = idx - lo;
    return Math.round((arr[lo] + frac * (arr[hi] - arr[lo])) * 100) / 100;
  }
  const q1 = pctile(sorted, 25);
  const q3 = pctile(sorted, 75);
  const iqr = Math.round((q3 - q1) * 100) / 100;
  const lowerFence = Math.round((q1 - 1.5 * iqr) * 100) / 100;
  const upperFence = Math.round((q3 + 1.5 * iqr) * 100) / 100;
  const outliers = sorted.filter(v => v < lowerFence || v > upperFence);
  return { q1, q3, iqr, lowerFence, upperFence, outliers };
}

