function pendulum(length, angleDeg, dt, steps) {
  const g = 9.8;
  let theta = angleDeg * Math.PI / 180;
  let omega = 0;
  const result = [];
  for (let i = 0; i <= steps; i++) {
    result.push({
      time: Math.round(i * dt * 10000) / 10000,
      angle: Math.round(theta * 180 / Math.PI * 100) / 100,
      angularVelocity: Math.round(omega * 10000) / 10000
    });
    const alpha = -(g / length) * Math.sin(theta);
    omega = omega + alpha * dt;
    theta = theta + omega * dt;
  }
  return result;
}

