function equilibrium(kc, initial, coefficients) {
  const [a, b, c, d] = coefficients;
  let [A, B, C, D] = initial;
  // Binary search for x
  let lo = 0, hi = Math.min(A / a, B / b);
  for (let iter = 0; iter < 100; iter++) {
    const x = (lo + hi) / 2;
    const eA = A - a * x;
    const eB = B - b * x;
    const eC = C + c * x;
    const eD = D + d * x;
    const q = Math.pow(eC, c) * Math.pow(eD, d) / (Math.pow(eA, a) * Math.pow(eB, b));
    if (q < kc) lo = x;
    else hi = x;
  }
  const x = (lo + hi) / 2;
  const r4 = v => Math.round(v * 10000) / 10000;
  return [r4(A - a * x), r4(B - b * x), r4(C + c * x), r4(D + d * x)];
}

