function kinetics(order, k, initial, times) {
  const r4 = v => Math.round(v * 10000) / 10000;
  let concentrations, halfLife;
  if (order === 0) {
    concentrations = times.map(t => r4(Math.max(0, initial - k * t)));
    halfLife = r4(initial / (2 * k));
  } else if (order === 1) {
    concentrations = times.map(t => r4(initial * Math.exp(-k * t)));
    halfLife = r4(Math.log(2) / k);
  } else {
    concentrations = times.map(t => r4(initial / (1 + initial * k * t)));
    halfLife = r4(1 / (k * initial));
  }
  return { concentrations, halfLife };
}

