function amortize(principal, annualRate, years) {
  const r = annualRate / 12;
  const n = years * 12;
  const monthlyPayment = Math.round(principal * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1) * 100) / 100;
  const totalPaid = Math.round(monthlyPayment * n * 100) / 100;
  const totalInterest = Math.round((totalPaid - principal) * 100) / 100;
  return { monthlyPayment, totalPaid, totalInterest };
}

